INSERT INTO "StaticPageTranslation" ("id", "pageId", "locale", "title", "body", "metaDescription", "updatedAt") VALUES ('static_about_en', 'static_about', 'en', $page$About us$page$, $page${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Who we are"}]},{"type":"paragraph","content":[{"type":"text","text":"RSnewslk.com is a Sri Lankan news website that publishes news in Sinhala and English. [[Add a short description of the publisher: the name of the organisation or person responsible for the website, and when it began publishing.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Our mission"}]},{"type":"paragraph","content":[{"type":"text","text":"Our mission is to give readers in Sri Lanka and around the world accurate, timely and clearly written news about the events that affect their lives, in the language they prefer."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Our vision"}]},{"type":"paragraph","content":[{"type":"text","text":"We want to be a news source that readers trust: one that reports carefully, explains clearly and treats every reader and every subject with fairness and respect."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What we cover"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"News from across Sri Lanka"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Politics and public affairs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Business and the economy"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"World news"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sport"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Entertainment and culture"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Video news and public opinion polls"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"[[Adjust this list to match the sections you publish.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Our commitment to readers"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We aim to report accurately and to correct mistakes promptly and openly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We keep news reporting separate from opinion and from advertising."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We do not knowingly publish rumours as fact."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We welcome questions, complaints and story ideas from readers."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Read our "},{"type":"text","text":"Editorial policy","marks":[{"type":"link","attrs":{"href":"/en/editorial-policy"}}]},{"type":"text","text":" to learn how we work, or "},{"type":"text","text":"contact us","marks":[{"type":"link","attrs":{"href":"/en/contact"}}]},{"type":"text","text":"."}]}]}$page$::jsonb, $page$RSnewslk.com is a Sri Lankan news website publishing in Sinhala and English.$page$, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
