INSERT INTO "StaticPageTranslation" ("id", "pageId", "locale", "title", "body", "metaDescription", "updatedAt") VALUES ('static_contact_si', 'static_contact', 'si', $page$අප අමතන්න$page$, $page${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"පාඨකයන්ගේ පණිවිඩ අපි සාදරයෙන් පිළිගනිමු. ඔබගේ පණිවිඩය නිවැරදි පුද්ගලයා වෙත ළඟා වීමට, ඊට වඩාත් ගැළපෙන සම්බන්ධතාව භාවිත කරන්න."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"සාමාන්‍ය විමසීම්"}]},{"type":"paragraph","content":[{"type":"text","text":"විද්‍යුත් තැපෑල: [[සාමාන්‍ය විමසීම් සඳහා විද්‍යුත් තැපැල් ලිපිනය]]"},{"type":"hardBreak"},{"type":"text","text":"දුරකථනය: [[දුරකථන අංකය, නැතහොත් මෙම පේළිය ඉවත් කරන්න]]"},{"type":"hardBreak"},{"type":"text","text":"ලිපිනය: [[තැපැල් ලිපිනය, නැතහොත් මෙම පේළිය ඉවත් කරන්න]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"පුවත් තොරතුරු සහ පුවත් ඉදිරිපත් කිරීම්"}]},{"type":"paragraph","content":[{"type":"text","text":"පුවතක් පිළිබඳ තොරතුරු ඔබ සතුව ඇත්නම්, [[පුවත් තොරතුරු සඳහා විද්‍යුත් තැපැල් ලිපිනය හෝ පණිවිඩ අංකය]] හරහා අප අමතන්න. එම තොරතුරු ඔබ දැනගත් ආකාරය සහ ඔබ හා සම්බන්ධ විය හැකි ආකාරය සඳහන් කරන්න. පළ කිරීමට පෙර අපි තොරතුරු පරීක්ෂා කරමු. නීතියෙන් අවශ්‍ය වන අවස්ථා හැර, මූලාශ්‍රයක අනන්‍යතාව ඔවුන්ගේ එකඟතාවයකින් තොරව අපි හෙළි නොකරමු."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"නිවැරදි කිරීම් සහ පැමිණිලි"}]},{"type":"paragraph","content":[{"type":"text","text":"අප පළ කළ යමක් සාවද්‍ය හෝ අසාධාරණ යැයි ඔබ සිතන්නේ නම්, ලිපියේ සබැඳිය, වැරදි යැයි ඔබ සිතන දෙය සහ හැකි නම් සාක්ෂි සමඟ [[නිවැරදි කිරීම් සඳහා විද්‍යුත් තැපැල් ලිපිනය]] වෙත ලියන්න. වැඩ කරන දින [[සංඛ්‍යාව]] ක් ඇතුළත පිළිතුරු දීමට අපි උත්සාහ කරමු. නිවැරදි කිරීම් අප හසුරුවන ආකාරය අපගේ "},{"type":"text","text":"සංස්කාරක ප්‍රතිපත්තියේ","marks":[{"type":"link","attrs":{"href":"/si/editorial-policy"}}]},{"type":"text","text":" විස්තර කර ඇත."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"වෙළඳ දැන්වීම් විමසීම්"}]},{"type":"paragraph","content":[{"type":"text","text":"RSnewslk.com හි වෙළඳ දැන්වීම් පළ කිරීම සඳහා [[වෙළඳ දැන්වීම් සඳහා විද්‍යුත් තැපැල් ලිපිනය හෝ දුරකථන අංකය]] අමතන්න."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"සංස්කාරක විමසීම්"}]},{"type":"paragraph","content":[{"type":"text","text":"අපගේ වාර්තාකරණය හෝ සංස්කාරක තීරණ පිළිබඳ ප්‍රශ්න සඳහා [[කර්තෘගේ විද්‍යුත් තැපැල් ලිපිනය]] හරහා කර්තෘ අමතන්න."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"පෞද්ගලිකත්ව විමසීම්"}]},{"type":"paragraph","content":[{"type":"text","text":"පුද්ගලික තොරතුරු පිළිබඳ ප්‍රශ්න සඳහා අපගේ "},{"type":"text","text":"පෞද්ගලිකත්ව ප්‍රතිපත්තිය","marks":[{"type":"link","attrs":{"href":"/si/privacy-policy"}}]},{"type":"text","text":" බලන්න, නැතහොත් [[පෞද්ගලිකත්ව විමසීම් සඳහා විද්‍යුත් තැපැල් ලිපිනය]] වෙත ලියන්න."}]}]}$page$::jsonb, $page$සාමාන්‍ය විමසීම්, පුවත් තොරතුරු, නිවැරදි කිරීම්, වෙළඳ දැන්වීම් සහ සංස්කාරක ප්‍රශ්න සඳහා RSnewslk.com අමතන ආකාරය.$page$, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "StaticPageTranslation" ("id", "pageId", "locale", "title", "body", "metaDescription", "updatedAt") VALUES ('static_contact_en', 'static_contact', 'en', $page$Contact us$page$, $page${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We welcome messages from readers. Please use the contact that best matches your message so that it reaches the right person."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"General enquiries"}]},{"type":"paragraph","content":[{"type":"text","text":"Email: [[general enquiries email address]]"},{"type":"hardBreak"},{"type":"text","text":"Telephone: [[telephone number, or delete this line]]"},{"type":"hardBreak"},{"type":"text","text":"Address: [[postal address, or delete this line]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"News tips and story submissions"}]},{"type":"paragraph","content":[{"type":"text","text":"If you have information about a news story, contact us at [[news tips email address or messaging number]]. Please tell us how you know the information and how we can reach you. We check information before we publish it, and we do not reveal a source's identity without their agreement unless the law requires it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Corrections and complaints"}]},{"type":"paragraph","content":[{"type":"text","text":"If you believe something we published is inaccurate or unfair, email [[corrections email address]] with the link to the article, what you believe is wrong and, if possible, evidence. We aim to respond within [[number]] working days. Our "},{"type":"text","text":"Editorial policy","marks":[{"type":"link","attrs":{"href":"/en/editorial-policy"}}]},{"type":"text","text":" explains how we handle corrections."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Advertising enquiries"}]},{"type":"paragraph","content":[{"type":"text","text":"For advertising on RSnewslk.com, contact [[advertising email address or telephone number]]."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Editorial enquiries"}]},{"type":"paragraph","content":[{"type":"text","text":"For questions about our reporting or editorial decisions, contact the editor at [[editor's email address]]."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Privacy enquiries"}]},{"type":"paragraph","content":[{"type":"text","text":"For questions about personal information, see our "},{"type":"text","text":"Privacy policy","marks":[{"type":"link","attrs":{"href":"/en/privacy-policy"}}]},{"type":"text","text":" or email [[privacy contact email address]]."}]}]}$page$::jsonb, $page$How to contact RSnewslk.com with general enquiries, news tips, corrections, advertising and editorial questions.$page$, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "StaticPage" ("id", "key", "slug", "sortOrder") VALUES ('static_privacy', 'privacy', 'privacy-policy', 3) ON CONFLICT DO NOTHING;
INSERT INTO "StaticPageTranslation" ("id", "pageId", "locale", "title", "body", "metaDescription", "updatedAt") VALUES ('static_privacy_si', 'static_privacy', 'si', $page$පෞද්ගලිකත්ව ප්‍රතිපත්තිය$page$, $page${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"[[නීතිමය සමාලෝචනයක් අවශ්‍යයි: මෙය ආරම්භක පෙළක් පමණි; නීති උපදෙසක් නොවේ. ශ්‍රී ලංකා නීතිය පිළිබඳ දැනුමැති සුදුසුකම් ලත් නීතිඥයෙකු ලවා සමාලෝචනය කරවා, සියලු තැන් පුරවා, ප්‍රකාශයට පත් කිරීමට පෙර මෙම සටහන ඉවත් කරන්න.]]"}]},{"type":"paragraph","content":[{"type":"text","text":"අවසන් වරට යාවත්කාලීන කළේ: [[දිනය]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. හැඳින්වීම"}]},{"type":"paragraph","content":[{"type":"text","text":"ඔබ මෙම වෙබ් අඩවිය භාවිත කරන විට RSnewslk.com (\"අපි\") රැස් කරන තොරතුරු මොනවාද, ඒවා රැස් කරන්නේ ඇයි, සහ ඒවා ආරක්ෂා කරන්නේ කෙසේද යන්න මෙම ප්‍රතිපත්තියෙන් පැහැදිලි කෙරේ. මෙම වෙබ් අඩවිය මෙහෙයවනු ලබන්නේ [[ප්‍රකාශකයාගේ නීත්‍යනුකූල නම සහ ලියාපදිංචි ලිපිනය, ඇත්නම්]] විසිනි."}]},{"type":"paragraph","content":[{"type":"text","text":"2022 අංක 9 දරන පුද්ගලික දත්ත ආරක්ෂණ පනත ඇතුළු අදාළ ශ්‍රී ලංකා නීතියට අනුකූලව පුද්ගලික තොරතුරු හැසිරවීමට අපි උත්සාහ කරමු. [[අදාළ අවශ්‍යතා සහ ලියාපදිංචි කිරීම් හෝ දත්ත ආරක්ෂණ නිලධාරී පිළිබඳ වගකීම් නීතිඥයෙකු සමඟ තහවුරු කරන්න.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. අප රැස් කරන තොරතුරු"}]},{"type":"paragraph","content":[{"type":"text","text":"ගිණුමක් සෑදීමකින් හෝ ඔබගේ නම හෝ සම්බන්ධතා විස්තර ලබා දීමකින් තොරව ඔබට RSnewslk.com කියවිය හැක. අප රැස් කරන්නේ පහත විස්තර කර ඇති සීමිත තොරතුරු පමණි."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. ඔබ අපට ලබා දෙන තොරතුරු"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"මත විමසුම් අදහස් සහ සංකේත නාම.","marks":[{"type":"bold"}]},{"type":"text","text":" මහජන මත විමසුමක ඡන්දය දෙන විට, අදහසක් සහ සංකේත නාමයක් එක් කිරීමට ඔබට තෝරාගත හැක. මේවා අනිවාර්ය නොවේ. අදහස් පෙන්වීමට පෙර අපගේ සංස්කාරකවරුන් විසින් පරීක්ෂා කරනු ලබන අතර, ඒවා මත විමසුම සමඟ පළ කළ හැක."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"අපට එවන පණිවිඩ.","marks":[{"type":"bold"}]},{"type":"text","text":" ඔබ අපට විද්‍යුත් තැපෑලක් හෝ පණිවිඩයක් එවන්නේ නම්, ඔබගේ නම, සම්බන්ධතා විස්තර සහ පණිවිඩයේ අන්තර්ගතය වැනි ඔබ එවීමට තෝරාගන්නා තොරතුරු අපට ලැබේ."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. ස්වයංක්‍රීයව රැස් වන තාක්ෂණික තොරතුරු"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"සේවාදායක ලොග්.","marks":[{"type":"bold"}]},{"type":"text","text":" බොහෝ වෙබ් අඩවි මෙන්ම, අපගේ වෙබ් සේවාදායකය සෑම ඉල්ලීමක්ම සටහන් කරයි: ජාල (IP) ලිපිනය, දිනය සහ වේලාව, ඉල්ලූ පිටුව සහ බ්‍රවුසරයේ හා උපාංගයේ වර්ගය. වෙබ් අඩවිය ක්‍රියාත්මකව හා ආරක්ෂිතව තබා ගැනීමට අපි මෙම වාර්තා භාවිත කරමු. ඒවා සීමිත කාලයක් තබාගෙන ස්වයංක්‍රීයව මකා දමනු ලැබේ. [[රඳවා තබා ගන්නා කාලය තහවුරු කරන්න.]]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"මත විමසුම් ඡන්දය.","marks":[{"type":"bold"}]},{"type":"text","text":" එක් උපාංගයකට එක් ඡන්දයක් පමණක් ඉඩ දීම සඳහා, ඔබ ඡන්දය දෙන විට වෙබ් අඩවිය ඔබගේ බ්‍රවුසරයට අහඹු උපාංග හඳුනාගැනීමක් ලබා දෙයි. අපි එය ගබඩා කරන්නේ ඔබගේ ඡන්දය සමඟ, ගුප්ත කළ (keyed hash) ආකාරයෙන් පමණි. අපයෝජන හඳුනාගැනීමට, සෑම දිනකම වෙනස් වන යතුරක් භාවිතයෙන් ඔබගේ ජාල ලිපිනයේ ගුප්ත කළ ආකාරයක් ද අපි සටහන් කරමු; එබැවින් එය නැවත ඔබගේ ලිපිනය බවට පත් කිරීමට හෝ දින අතර සැසඳීමට නොහැක."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"කියවීම් සංඛ්‍යාලේඛන.","marks":[{"type":"bold"}]},{"type":"text","text":" සෑම ලිපියක්ම දිනකට කී වතාවක් කියවූයේද, සහ වෙබ් අඩවියේ සෑම වෙළඳ දැන්වීමක්ම දිනකට කී වතාවක් පෙන්වූයේද ක්ලික් කළේද යන්න අපි ගණන් කරමු. මේවා එකතුව පමණක් වන අතර තනි අමුත්තන් සමඟ සම්බන්ධ නොවේ."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. කුකී සහ ඊට සමාන තාක්ෂණ"}]},{"type":"paragraph","content":[{"type":"text","text":"අපි වෙළඳ දැන්වීම් කුකී හෝ විශ්ලේෂණ කුකී භාවිත නොකරමු. වෙබ් අඩවිය භාවිත කරන්නේ:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ඉහත විස්තර කළ මත විමසුම් උපාංග හඳුනාගැනීම රඳවා ගන්නා කුකියක්; එය සකසනු ලබන්නේ ඔබ මත විමසුමක ඡන්දය දෙන විට පමණි;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"වෙබ් අඩවියේ පරිපාලකයන් සඳහා පිවිසුම් කුකියක්; සාමාන්‍ය අමුත්තන්ට එය නොලැබේ."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. වෙබ් අඩවි විශ්ලේෂණ"}]},{"type":"paragraph","content":[{"type":"text","text":"අපි දැනට තුන්වන පාර්ශ්වීය විශ්ලේෂණ සේවාවක් භාවිත නොකරමු. එවැනි සේවාවක් හඳුන්වා දෙන්නේ නම්, එය භාවිත කිරීමට පෙර, සේවා සපයන්නාගේ නම සහ එය රැස් කරන දෑ සඳහන් කරමින් අපි මෙම ප්‍රතිපත්තිය යාවත්කාලීන කරන්නෙමු. [[පසුව හඳුන්වා දෙන විශ්ලේෂණ සේවා සපයන්නා: නම, අරමුණ, රැස් කරන තොරතුරු, එහි පෞද්ගලිකත්ව ප්‍රතිපත්තියට සබැඳිය.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. වෙළඳ දැන්වීම් සහ තුන්වන පාර්ශ්වීය සේවා"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"වෙළඳ දැන්වීම්.","marks":[{"type":"bold"}]},{"type":"text","text":" වෙබ් අඩවියේ වෙළඳ දැන්වීම් අප විසින්ම සෘජුවම පළ කරනු ලැබේ. අපි වෙළඳ දැන්වීම් ජාල භාවිත නොකරන අතර, වෙළඳ දැන්වීම්කරුවන්ට අමුත්තන් පිළිබඳ කිසිදු පුද්ගලික තොරතුරක් අපෙන් නොලැබේ. වෙළඳ දැන්වීම් ජාලයක් හඳුන්වා දෙන්නේ නම්, ඊට පෙර අපි මෙම ප්‍රතිපත්තිය යාවත්කාලීන කරන්නෙමු. [[පසුව හඳුන්වා දෙන වෙළඳ දැන්වීම් ජාල.]]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"වීඩියෝ.","marks":[{"type":"bold"}]},{"type":"text","text":" සමහර වීඩියෝ YouTube හි ඇත. වීඩියෝවක් YouTube (youtube-nocookie.com) වෙතින් පූරණය වන්නේ ඔබ එය වාදනය කිරීමට ක්ලික් කළ පසුව පමණි. එතැන් සිට, Google විසින් මෙහෙයවනු ලබන YouTube, තමන්ගේම පෞද්ගලිකත්ව ප්‍රතිපත්තිය යටතේ තොරතුරු සකසයි."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"බෙදාගැනීමේ බොත්තම්.","marks":[{"type":"bold"}]},{"type":"text","text":" WhatsApp සහ Facebook බෙදාගැනීමේ බොත්තම් සාමාන්‍ය සබැඳි පමණි. ඔබ බොත්තමක් ක්ලික් කරන්නේ නැත්නම් එම සේවා වෙත කිසිදු තොරතුරක් නොයැවේ."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"සත්කාරකත්වය.","marks":[{"type":"bold"}]},{"type":"text","text":" වෙබ් අඩවිය [[රටේ නම]] හි පිහිටි සේවාදායකවල [[සත්කාරක සේවා සපයන්නා]] විසින් සත්කාරකත්වය සපයනු ලැබේ."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. අපි තොරතුරු භාවිත කරන ආකාරය"}]},{"type":"paragraph","content":[{"type":"text","text":"වෙබ් අඩවිය පළ කිරීමට හා පවත්වාගෙන යාමට; එය ආරක්ෂිතව තබා ගැනීමට සහ වංචනික මත විමසුම් ඡන්ද ඇතුළු අපයෝජන වැළැක්වීමට; මත විමසුම් අදහස් පරීක්ෂා කර පළ කිරීමට; ඔබගේ පණිවිඩවලට පිළිතුරු දීමට; සහ කියවන අන්තර්ගතය කුමක්දැයි එකතුව පමණක් භාවිතයෙන් තේරුම් ගැනීමට අපි තොරතුරු භාවිත කරමු."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"9. තොරතුරු බෙදාගැනීම"}]},{"type":"paragraph","content":[{"type":"text","text":"අපි පුද්ගලික තොරතුරු විකුණන්නේ නැත. අපි ඒවා බෙදාගන්නේ අපගේ සත්කාරක සේවා සපයන්නා වැනි, වෙබ් අඩවිය පවත්වාගෙන යාමට උදව් කරන සේවා සපයන්නන් සමඟ, එම අරමුණට අවශ්‍ය ප්‍රමාණයට පමණි; නැතහොත් නීතියෙන් අවශ්‍ය වූ විට, හෝ අපගේ පාඨකයන්ගේ, කාර්ය මණ්ඩලයේ හෝ වෙනත් අයගේ අයිතිවාසිකම් හා ආරක්ෂාව රැකීමට අවශ්‍ය වූ විට පමණි."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"10. තොරතුරු රඳවා තබා ගැනීම"}]},{"type":"paragraph","content":[{"type":"text","text":"ඉහත අරමුණු සඳහා අවශ්‍ය කාලය පමණක් අපි තොරතුරු තබා ගනිමු. [[රඳවා තබා ගන්නා කාලයන් සඳහන් කරන්න: සේවාදායක ලොග්; මත විමසුම් ඡන්ද සහ ඡන්ද වාර්තා; මත විමසුම් අදහස්; ප්‍රතික්ෂේප වූ ඡන්ද උත්සාහයන්ගේ වාර්තා; අපට එවන පණිවිඩ.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"11. දත්ත ආරක්ෂාව"}]},{"type":"paragraph","content":[{"type":"text","text":"සංකේතනය කළ සම්බන්ධතා (HTTPS), පරිපාලන පද්ධතිවලට සීමිත ප්‍රවේශය සහ ඡන්ද හඳුනාගැනීම් ගුප්ත කළ ආකාරයෙන් පමණක් ගබඩා කිරීම ඇතුළුව, තොරතුරු ආරක්ෂා කිරීමට අපි සාධාරණ තාක්ෂණික හා සංවිධානාත්මක පියවර ගනිමු. කිසිදු සම්ප්‍රේෂණ හෝ ගබඩා ක්‍රමයක් සම්පූර්ණයෙන්ම ආරක්ෂිත නොවේ."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"12. ඔබගේ අයිතිවාසිකම් සහ පෞද්ගලිකත්ව විමසීම්"}]},{"type":"paragraph","content":[{"type":"text","text":"අදාළ නීතියට යටත්ව, ඔබ පිළිබඳ පුද්ගලික තොරතුරු වෙත ප්‍රවේශය, ඒවා නිවැරදි කිරීම හෝ මකා දැමීම ඉල්ලීමට, හෝ ඒවා භාවිත කරන ආකාරයට විරුද්ධ වීමට ඔබට අයිතියක් තිබිය හැක. ඉල්ලීමක් කිරීමට, පහත විස්තර භාවිතයෙන් අප අමතන්න. [[නීතිමය සමාලෝචනයෙන් පසු, ඉල්ලීම් හසුරුවන ආකාරය සහ පිළිතුරු දෙන කාලය විස්තර කරන්න.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"13. මෙම ප්‍රතිපත්තියේ වෙනස්කම්"}]},{"type":"paragraph","content":[{"type":"text","text":"උදාහරණයක් ලෙස විශ්ලේෂණ, වෙළඳ දැන්වීම් ජාල, පුවත් ලිපි (newsletter) හෝ තොරතුරු රැස් කරන වෙනත් සේවා හඳුන්වා දීමට පෙර, අපි මෙම ප්‍රතිපත්තිය යාවත්කාලීන කළ හැක. එය අවසන් වරට වෙනස් කළ දිනය ඉහළින් දැක්වේ."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"14. සම්බන්ධ වීම"}]},{"type":"paragraph","content":[{"type":"text","text":"පෞද්ගලිකත්වය පිළිබඳ ප්‍රශ්න සඳහා [[පෞද්ගලිකත්ව සම්බන්ධතාවයේ නම හෝ තනතුර]] හට [[පෞද්ගලිකත්ව විමසීම් සඳහා විද්‍යුත් තැපැල් ලිපිනය]] හෝ [[තැපැල් ලිපිනය]] හරහා ලියන්න. අපගේ "},{"type":"text","text":"සම්බන්ධතා පිටුව","marks":[{"type":"link","attrs":{"href":"/si/contact"}}]},{"type":"text","text":" ද බලන්න."}]}]}$page$::jsonb, $page$RSnewslk.com අමුත්තන් පිළිබඳ තොරතුරු රැස් කරන, භාවිත කරන සහ ආරක්ෂා කරන ආකාරය.$page$, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "StaticPageTranslation" ("id", "pageId", "locale", "title", "body", "metaDescription", "updatedAt") VALUES ('static_privacy_en', 'static_privacy', 'en', $page$Privacy policy$page$, $page${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"[[Legal review required: this is starter text, not legal advice. Have it reviewed by a qualified legal professional familiar with Sri Lankan law, complete every placeholder, and then delete this note before publishing.]]"}]},{"type":"paragraph","content":[{"type":"text","text":"Last updated: [[date]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Introduction"}]},{"type":"paragraph","content":[{"type":"text","text":"This policy explains what information RSnewslk.com (\"we\", \"us\") collects when you use this website, why we collect it, and how we protect it. The website is operated by [[legal name of the publisher, and registered address if any]]."}]},{"type":"paragraph","content":[{"type":"text","text":"We aim to handle personal information in line with applicable Sri Lankan law, including the Personal Data Protection Act, No. 9 of 2022. [[Confirm the applicable requirements, and any registration or data protection officer obligations, with a legal professional.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Information we collect"}]},{"type":"paragraph","content":[{"type":"text","text":"You can read RSnewslk.com without creating an account or giving us your name or contact details. We collect only the limited information described below."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Information you give us"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Poll comments and code names.","marks":[{"type":"bold"}]},{"type":"text","text":" When you vote in a public opinion poll, you may choose to add a comment and a code name. These are optional. Comments are checked by our editors before they are shown, and may be published with the poll."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Messages to us.","marks":[{"type":"bold"}]},{"type":"text","text":" If you email or message us, we receive the information you choose to send, such as your name, contact details and the content of your message."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Technical information collected automatically"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Server logs.","marks":[{"type":"bold"}]},{"type":"text","text":" Like most websites, our web server records each request: the network (IP) address, date and time, the page requested and the type of browser and device. We use these records to keep the website working and secure. They are kept for a limited period and then deleted automatically. [[Confirm the retention period.]]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Poll voting.","marks":[{"type":"bold"}]},{"type":"text","text":" To allow one vote per device, the site gives your browser a random device identifier when you vote. We store only a scrambled (keyed hash) form of it, together with your vote. To detect abuse, we also record a scrambled form of your network address using a key that changes every day, so it cannot be turned back into your address or compared across days."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reading statistics.","marks":[{"type":"bold"}]},{"type":"text","text":" We count how many times each article is read each day, and how many times each advertisement on the site is shown and clicked each day. These are totals only and are not linked to individual visitors."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Cookies and similar technologies"}]},{"type":"paragraph","content":[{"type":"text","text":"We do not use advertising cookies or analytics cookies. The website uses:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"a cookie that holds the poll-voting device identifier described above, set only when you vote in a poll;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"a sign-in cookie for the website's administrators, which ordinary visitors do not receive."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. Website analytics"}]},{"type":"paragraph","content":[{"type":"text","text":"We do not currently use a third-party analytics service. If we introduce one, we will update this policy before it is used, naming the provider and explaining what it collects. [[Analytics provider, if introduced later: name, purpose, information collected, link to its privacy policy.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. Advertising and third-party services"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Advertising.","marks":[{"type":"bold"}]},{"type":"text","text":" Advertisements on the site are placed by us directly. We do not use advertising networks, and advertisers receive no personal information about visitors from us. If we introduce an advertising network, we will update this policy first. [[Advertising networks, if introduced later.]]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Videos.","marks":[{"type":"bold"}]},{"type":"text","text":" Some videos are hosted on YouTube. A video is loaded from YouTube (youtube-nocookie.com) only after you click to play it. From then on, YouTube, which is operated by Google, processes information under its own privacy policy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Share buttons.","marks":[{"type":"bold"}]},{"type":"text","text":" The WhatsApp and Facebook share buttons are ordinary links. No information is sent to those services unless you click a button."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hosting.","marks":[{"type":"bold"}]},{"type":"text","text":" The website is hosted by [[hosting provider]] on servers located in [[country]]."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. How we use information"}]},{"type":"paragraph","content":[{"type":"text","text":"We use information to publish and run the website; keep it secure and prevent abuse, including fraudulent poll voting; moderate and publish poll comments; respond to your messages; and understand which content is read, using totals only."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"9. Sharing information"}]},{"type":"paragraph","content":[{"type":"text","text":"We do not sell personal information. We share it only with service providers who help us run the website, such as our hosting provider, and only as needed for that purpose; or when required by law or to protect the rights and safety of our readers, staff or others."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"10. Data retention"}]},{"type":"paragraph","content":[{"type":"text","text":"We keep information only for as long as it is needed for the purposes above. [[State retention periods for: server logs; poll votes and voting records; poll comments; records of rejected voting attempts; messages sent to us.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"11. Data security"}]},{"type":"paragraph","content":[{"type":"text","text":"We use reasonable technical and organisational measures to protect information, including encrypted connections (HTTPS), restricted access to administrative systems and storing voting identifiers only in scrambled form. No method of transmission or storage is completely secure."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"12. Your rights and privacy enquiries"}]},{"type":"paragraph","content":[{"type":"text","text":"Subject to applicable law, you may have the right to ask for access to, correction of or deletion of personal information about you, or to object to how it is used. To make a request, contact us using the details below. [[Describe how requests are handled and the response time, after legal review.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"13. Changes to this policy"}]},{"type":"paragraph","content":[{"type":"text","text":"We may update this policy, for example before introducing analytics, advertising networks, newsletters or other services that collect information. The date at the top shows when it was last changed."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"14. Contact"}]},{"type":"paragraph","content":[{"type":"text","text":"For privacy questions, contact [[privacy contact name or role]] at [[privacy contact email address]] or [[postal address]]. See also our "},{"type":"text","text":"Contact page","marks":[{"type":"link","attrs":{"href":"/en/contact"}}]},{"type":"text","text":"."}]}]}$page$::jsonb, $page$How RSnewslk.com collects, uses and protects information about visitors.$page$, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "StaticPage" ("id", "key", "slug", "sortOrder") VALUES ('static_terms', 'terms', 'terms-and-conditions', 4) ON CONFLICT DO NOTHING;
INSERT INTO "StaticPageTranslation" ("id", "pageId", "locale", "title", "body", "metaDescription", "updatedAt") VALUES ('static_terms_si', 'static_terms', 'si', $page$නියම සහ කොන්දේසි$page$, $page${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"[[නීතිමය සමාලෝචනයක් අවශ්‍යයි: මෙය ආරම්භක පෙළක් පමණි; නීති උපදෙසක් නොවේ. ශ්‍රී ලංකා නීතිය පිළිබඳ දැනුමැති සුදුසුකම් ලත් නීතිඥයෙකු ලවා සමාලෝචනය කරවා, සියලු තැන් පුරවා, ප්‍රකාශයට පත් කිරීමට පෙර මෙම සටහන ඉවත් කරන්න.]]"}]},{"type":"paragraph","content":[{"type":"text","text":"අවසන් වරට යාවත්කාලීන කළේ: [[දිනය]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. මෙම නියම පිළිගැනීම"}]},{"type":"paragraph","content":[{"type":"text","text":"මෙම නියම අදාළ වන්නේ [[ප්‍රකාශකයාගේ නීත්‍යනුකූල නම]] විසින් මෙහෙයවනු ලබන RSnewslk.com ඔබ භාවිත කිරීමටයි. වෙබ් අඩවිය භාවිත කිරීමෙන් ඔබ මෙම නියමවලට එකඟ වේ. ඔබ එකඟ නොවන්නේ නම්, කරුණාකර වෙබ් අඩවිය භාවිත නොකරන්න."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. වෙබ් අඩවිය භාවිත කිරීම"}]},{"type":"paragraph","content":[{"type":"text","text":"ඔබගේ පුද්ගලික, වාණිජ නොවන භාවිතය සඳහා මෙම වෙබ් අඩවියේ අන්තර්ගතය කියවීමට සහ ඒවායේ සබැඳි බෙදාගැනීමට ඔබට හැක. වෙබ් අඩවිය නීත්‍යනුකූලව සහ අන් අයගේ භාවිතයට බාධා නොවන ආකාරයෙන් භාවිත කිරීමට ඔබ එකඟ වේ."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. බුද්ධිමය දේපළ සහ ප්‍රකාශන හිමිකම"}]},{"type":"paragraph","content":[{"type":"text","text":"වෙනත් ආකාරයකින් සඳහන් කර නොමැති නම්, මෙම වෙබ් අඩවියේ ලිපි, ඡායාරූප, වීඩියෝ, ග්‍රැෆික් සහ නිර්මාණය [[ප්‍රකාශකයාගේ නීත්‍යනුකූල නම]] සතු වේ, නැතහොත් අවසරය ඇතිව භාවිත කෙරේ. නීතියෙන් ඉඩ දෙන අවස්ථා හැර, අපගේ ලිඛිත අවසරයකින් තොරව අපගේ අන්තර්ගතය සම්පූර්ණයෙන් හෝ සැලකිය යුතු කොටසක් පිටපත් කිරීම, නැවත පළ කිරීම, විකාශනය කිරීම හෝ බෙදා හැරීම නොකළ යුතුය. මුල් ලිපියට පැහැදිලි ගෞරවයක් සහ සබැඳියක් සහිත කෙටි උපුටා දැක්වීම් සාදරයෙන් පිළිගනිමු. [[ඔබ ලබා දීමට කැමති නැවත භාවිත ප්‍රතිපත්තිය තහවුරු කරන්න.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. ඔබ ඉදිරිපත් කරන අන්තර්ගතය"}]},{"type":"paragraph","content":[{"type":"text","text":"ඔබ මත විමසුම් අදහසක් හෝ වෙනත් අන්තර්ගතයක් ඉදිරිපත් කරන විට, එය ඔබගේම බවත්, නීත්‍යනුකූල බවත්, කිසිවෙකුගේ අයිතිවාසිකම් උල්ලංඝනය නොකරන බවත් ඔබ තහවුරු කරයි. එය පළ කිරීමට, දිග හා පැහැදිලි බව සඳහා සංස්කරණය කිරීමට, හෝ පළ නොකිරීමට ඔබ අපට ඉඩ දෙයි. අදහස් පරීක්ෂාවට ලක් කෙරෙන අතර, අපගේ අභිමතය පරිදි ඕනෑම අන්තර්ගතයක් ඉවත් කළ හැක. අදහස්වල ඔබගේ හෝ අන් අයගේ පුද්ගලික තොරතුරු ඇතුළත් නොකරන්න."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. තොරතුරුවල නිරවද්‍යතාව සහ ලබාගත හැකි බව"}]},{"type":"paragraph","content":[{"type":"text","text":"අපගේ වාර්තාකරණය නිවැරදි කිරීමට අපි වෙහෙසෙමු, නමුත් පුවත් වර්ධනය වන අතර වැරදි සිදු විය හැක. අන්තර්ගතය සපයනු ලබන්නේ සාමාන්‍ය තොරතුරු සඳහා වන අතර එය යාවත්කාලීන හෝ නිවැරදි කළ හැක. වෙබ් අඩවිය සැමවිටම ලබාගත හැකි බවට හෝ දෝෂවලින් තොර බවට අපි පොරොන්දු නොවන අතර, ඕනෑම වේලාවක අන්තර්ගතය වෙනස් කිරීමට හෝ ඉවත් කිරීමට අපට හැක."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. බාහිර සබැඳි"}]},{"type":"paragraph","content":[{"type":"text","text":"වෙබ් අඩවියේ වෙනත් වෙබ් අඩවිවලට සබැඳි තිබිය හැක. ඒවායේ අන්තර්ගතය, ලබාගත හැකි බව හෝ පෞද්ගලිකත්ව පිළිවෙත් සම්බන්ධයෙන් අපි වගකියන්නේ නැත. සබැඳියක් යනු අප එම වෙබ් අඩවිය අනුමත කරන බව නොවේ."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. තහනම් ක්‍රියාකාරකම්"}]},{"type":"paragraph","content":[{"type":"text","text":"ඔබ පහත දෑ නොකළ යුතුය:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"වෙබ් අඩවියට, එහි සේවාදායකවලට හෝ පද්ධතිවලට අනවසර ප්‍රවේශයක් ලබා ගැනීමට උත්සාහ කිරීම;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"උදාහරණයක් ලෙස අධික බරක් පැටවීමෙන් හෝ හානිකර කේත ඇතුළු කිරීමෙන් වෙබ් අඩවියට බාධා කිරීම;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"මත විමසුම්වල එක් වරකට වඩා ඡන්දය දීමට හෝ ප්‍රතිඵල හැසිරවීමට ස්වයංක්‍රීය ක්‍රම භාවිත කිරීම;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"අවසරයකින් තොරව, උදාහරණයක් ලෙස ස්වයංක්‍රීය ක්‍රම මගින්, අන්තර්ගතය තොග වශයෙන් පිටපත් කිරීම;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"නීති විරෝධී, අපහාසාත්මක, වෛරී, තර්ජනාත්මක, අසභ්‍ය හෝ නොමඟ යවන, නැතහොත් කිසිවෙකුගේ අයිතිවාසිකම් උල්ලංඝනය කරන අන්තර්ගතය ඉදිරිපත් කිරීම."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. වගකීම් සීමා කිරීම"}]},{"type":"paragraph","content":[{"type":"text","text":"නීතියෙන් ඉඩ දෙන තරමට, ඔබ වෙබ් අඩවිය භාවිත කිරීමෙන් හෝ එහි අන්තර්ගතය මත විශ්වාසය තැබීමෙන් ඇති වන කිසිදු පාඩුවක් සඳහා [[ප්‍රකාශකයාගේ නීත්‍යනුකූල නම]] වගකියනු නොලැබේ. නීතියෙන් බැහැර කළ නොහැකි වගකීමක් මෙම නියමවලින් බැහැර නොකෙරේ. [[මෙම වචන නීතිඥයෙකු විසින් සමාලෝචනය කළ යුතුය.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"9. මෙම නියමවල වෙනස්කම්"}]},{"type":"paragraph","content":[{"type":"text","text":"අපි කලින් කල මෙම නියම යාවත්කාලීන කළ හැක. ඒවා අවසන් වරට වෙනස් කළ දිනය ඉහළින් දැක්වේ. වෙනසකින් පසු වෙබ් අඩවිය දිගටම භාවිත කිරීමෙන්, ඔබ යාවත්කාලීන නියම පිළිගන්නා බව අදහස් වේ."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"10. පාලන නීතිය සහ සම්බන්ධ වීම"}]},{"type":"paragraph","content":[{"type":"text","text":"මෙම නියම ශ්‍රී ලංකාවේ නීතිවලට යටත් වේ. [[පාලන නීතිය සහ අධිකරණ බලය නීතිඥයෙකු සමඟ තහවුරු කරන්න.]] මෙම නියම පිළිබඳ ප්‍රශ්න සඳහා [[සම්බන්ධතා විද්‍යුත් තැපැල් ලිපිනය]] හරහා හෝ අපගේ "},{"type":"text","text":"සම්බන්ධතා පිටුව","marks":[{"type":"link","attrs":{"href":"/si/contact"}}]},{"type":"text","text":" හරහා අප අමතන්න."}]}]}$page$::jsonb, $page$RSnewslk.com වෙබ් අඩවිය භාවිත කිරීමට අදාළ නියම.$page$, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "StaticPageTranslation" ("id", "pageId", "locale", "title", "body", "metaDescription", "updatedAt") VALUES ('static_terms_en', 'static_terms', 'en', $page$Terms and conditions$page$, $page${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"[[Legal review required: this is starter text, not legal advice. Have it reviewed by a qualified legal professional familiar with Sri Lankan law, complete every placeholder, and then delete this note before publishing.]]"}]},{"type":"paragraph","content":[{"type":"text","text":"Last updated: [[date]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Acceptance of these terms"}]},{"type":"paragraph","content":[{"type":"text","text":"These terms apply to your use of RSnewslk.com, operated by [[legal name of the publisher]]. By using the website you agree to them. If you do not agree, please do not use the website."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Using the website"}]},{"type":"paragraph","content":[{"type":"text","text":"You may read, and share links to, the content on this website for your personal, non-commercial use. You agree to use the website lawfully and in a way that does not interfere with other people's use of it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Intellectual property and copyright"}]},{"type":"paragraph","content":[{"type":"text","text":"Unless stated otherwise, the articles, photographs, videos, graphics and design of this website belong to [[legal name of the publisher]] or are used with permission. You may not copy, republish, broadcast or distribute our content, in whole or in substantial part, without our written permission, except as allowed by law. Short quotations with a clear credit and link to the original article are welcome. [[Confirm the reuse policy you want to offer.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Content you submit"}]},{"type":"paragraph","content":[{"type":"text","text":"When you submit a poll comment or other content, you confirm that it is your own, that it is lawful, and that it does not infringe anyone's rights. You allow us to publish, edit for length and clarity, or decline to publish it. Comments are moderated, and we may remove any content at our discretion. Do not submit personal information about yourself or others in comments."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Accuracy and availability of information"}]},{"type":"paragraph","content":[{"type":"text","text":"We work to make our reporting accurate, but news develops and mistakes can happen. Content is provided for general information and may be updated or corrected. We do not promise that the website will always be available or free of errors, and we may change or withdraw content at any time."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. External links"}]},{"type":"paragraph","content":[{"type":"text","text":"The website may link to other websites. We are not responsible for their content, availability or privacy practices. A link does not mean we endorse a website."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. Prohibited activities"}]},{"type":"paragraph","content":[{"type":"text","text":"You must not:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"attempt to gain unauthorised access to the website, its servers or its systems;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"disrupt the website, for example by overloading it or introducing harmful code;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"use automated means to vote more than once in polls or to manipulate results;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"copy content in bulk, for example by automated scraping, without permission;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"submit content that is unlawful, defamatory, hateful, threatening, obscene or misleading, or that infringes anyone's rights."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. Limitation of liability"}]},{"type":"paragraph","content":[{"type":"text","text":"To the extent permitted by law, [[legal name of the publisher]] is not liable for any loss arising from your use of the website or reliance on its content. Nothing in these terms excludes liability that cannot be excluded by law. [[Wording to be reviewed by a legal professional.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"9. Changes to these terms"}]},{"type":"paragraph","content":[{"type":"text","text":"We may update these terms from time to time. The date at the top shows when they were last changed. Continuing to use the website after a change means you accept the updated terms."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"10. Governing law and contact"}]},{"type":"paragraph","content":[{"type":"text","text":"These terms are governed by the laws of Sri Lanka. [[Confirm governing law and jurisdiction with a legal professional.]] For questions about these terms, contact us at [[contact email address]] or through our "},{"type":"text","text":"Contact page","marks":[{"type":"link","attrs":{"href":"/en/contact"}}]},{"type":"text","text":"."}]}]}$page$::jsonb, $page$The terms that apply to using the RSnewslk.com website.$page$, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "StaticPage" ("id", "key", "slug", "sortOrder") VALUES ('static_editorial', 'editorial', 'editorial-policy', 5) ON CONFLICT DO NOTHING;
INSERT INTO "StaticPageTranslation" ("id", "pageId", "locale", "title", "body", "metaDescription", "updatedAt") VALUES ('static_editorial_si', 'static_editorial', 'si', $page$සංස්කාරක ප්‍රතිපත්තිය$page$, $page${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"පුවත් රැස් කිරීම, පරීක්ෂා කිරීම සහ පළ කිරීමේදී අප අනුගමනය කරන ප්‍රමිතීන් මෙම ප්‍රතිපත්තියෙන් විස්තර කෙරේ. [[ඔබගේ සංස්කාරක කණ්ඩායම සමඟ මෙම ප්‍රමිතීන් සමාලෝචනය කර, ඔබ ඇත්ත වශයෙන්ම වැඩ කරන ආකාරයට ගැළපෙන සේ සකස් කරන්න.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"සංස්කාරක ස්වාධීනත්වය"}]},{"type":"paragraph","content":[{"type":"text","text":"අපගේ සංස්කාරක තීරණ ගනු ලබන්නේ පුවත් වටිනාකම සහ මහජන යහපත පදනම් කරගෙන අපගේ සංස්කාරකවරුන් විසිනි. අප වාර්තා කරන්නේ කුමක්ද, කෙසේද යන්න තීරණය කරන්නේ වෙළඳ දැන්වීම්කරුවන්, අනුග්‍රාහකයන්, හිමිකරුවන්, දේශපාලන පක්ෂ හෝ වෙනත් බාහිර පාර්ශ්ව නොවේ."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"නිරවද්‍යතාව සහ තහවුරු කිරීම"}]},{"type":"paragraph","content":[{"type":"text","text":"කරුණු නිවැරදිව ඉදිරිපත් කිරීම අපගේ අරමුණයි. පළ කිරීමට පෙර, විශ්වාසදායක මූලාශ්‍ර සමඟ, හැකි සෑම විටම මූලාශ්‍ර එකකට වඩා සමඟ, අපි තොරතුරු පරීක්ෂා කරමු. තොරතුරක් තවමත් තහවුරු කළ නොහැකි විට, අපි එය පැහැදිලිව සඳහන් කරමු; කටකතා හෝ චෝදනා කරුණු ලෙස ඉදිරිපත් නොකරමු. සංඛ්‍යා, නම්, දින සහ උපුටා දැක්වීම් සම්බන්ධයෙන් අපි විශේෂ සැලකිල්ලක් දක්වමු."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"මූලාශ්‍ර"}]},{"type":"paragraph","content":[{"type":"text","text":"අපි නම් සඳහන් කළ, සෘජු මූලාශ්‍රවලට ප්‍රමුඛත්වය දෙමු. නම් නොකළ මූලාශ්‍ර භාවිත කරන්නේ තොරතුරු වැදගත් වන සහ වෙනත් ආකාරයකින් ලබාගත නොහැකි විට පමණක් වන අතර, මූලාශ්‍රයේ නම සඳහන් නොකළේ ඇයිද යන්න අපි පැහැදිලි කරමු. රහසිගත මූලාශ්‍රවල අනන්‍යතාව අපි ආරක්ෂා කරමු."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"සාධාරණත්වය සහ අපක්ෂපාතීත්වය"}]},{"type":"paragraph","content":[{"type":"text","text":"අපි සාධාරණව සහ පක්ෂග්‍රාහීත්වයකින් තොරව වාර්තා කරමු. පුද්ගලයන්ට හෝ ආයතනවලට එරෙහි විවේචන හෝ චෝදනා වාර්තා කරන විට, ඔවුන්ට පිළිතුරු දීමට අවස්ථාවක් ලබා දීමට අපි සාධාරණ උත්සාහයක් දරන අතර, ඔවුන්ගේ පිළිතුර ද වාර්තා කරමු."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"පුවත්, මතය සහ වෙළඳ දැන්වීම් වෙන් කිරීම"}]},{"type":"paragraph","content":[{"type":"text","text":"පුවත් වාර්තා මතයෙන් වෙන්ව තබනු ලැබේ. වෙළඳ දැන්වීම් පැහැදිලිව හඳුනාගත හැකි ලෙස දක්වනු ලබන අතර, මුදල් ගෙවූ අන්තර්ගතය කිසි විටෙක ස්වාධීන පුවත් ලෙස ඉදිරිපත් නොකෙරේ."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"නිවැරදි කිරීම්"}]},{"type":"paragraph","content":[{"type":"text","text":"අප සැලකිය යුතු වැරැද්දක් කළ විට, එය ඉක්මනින් නිවැරදි කර, ලිපිය නිවැරදි කළ බව සඳහන් කරමු. අක්ෂර වින්‍යාසය වැනි සුළු දෝෂ සටහනකින් තොරව නිවැරදි කළ හැක. දෝෂයක් වාර්තා කිරීමට අපගේ "},{"type":"text","text":"සම්බන්ධතා පිටුව","marks":[{"type":"link","attrs":{"href":"/si/contact"}}]},{"type":"text","text":" බලන්න."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"පෞද්ගලිකත්වය, හානිය සහ සංවේදී මාතෘකා"}]},{"type":"paragraph","content":[{"type":"text","text":"අපි මිනිසුන්ගේ පෞද්ගලිකත්වයට ගරු කරන අතර, එයට ඇතුළු වන්නේ පැහැදිලි මහජන යහපතක් ඇති විට පමණි. ළමයින්, අපරාධවලින් පීඩාවට පත් වූවන්, ශෝකයෙන් පසුවන අය, සියදිවි නසා ගැනීම සහ මානසික සෞඛ්‍යය පිළිබඳ වාර්තා කිරීමේදී අපි විශේෂ සැලකිල්ලක් දක්වන අතර, අනවශ්‍ය භයානක විස්තර මගහරිමු."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"අවශ්‍යතා ගැටුම්"}]},{"type":"paragraph","content":[{"type":"text","text":"අපගේ මාධ්‍යවේදීන් තමන්ට පුද්ගලික, මූල්‍ය හෝ පවුල් සම්බන්ධතාවයක් ඇති කරුණු ගැන වාර්තා නොකරන අතර, තම වාර්තාකරණයට බලපෑම් කළ හැකි තෑගි හෝ ගෙවීම් භාර නොගනිති. [[ඔබගේම නීති එක් කරන්න, උදාහරණයක් ලෙස තෑගි සහ බාහිර රැකියා පිළිබඳව.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"කෘත්‍රිම බුද්ධිය භාවිතය"}]},{"type":"paragraph","content":[{"type":"text","text":"සිංහල සහ ඉංග්‍රීසි අතර පරිවර්තනය, ව්‍යාකරණ නිවැරදි කිරීම හෝ සිරස්තල යෝජනා කිරීම වැනි කාර්යයන් සඳහා අපි කෘත්‍රිම බුද්ධි මෙවලම් භාවිත කළ හැක. එවැනි සෑම පෙළක්ම පළ කිරීමට පෙර අපගේ සංස්කාරක කණ්ඩායමේ සාමාජිකයෙකු විසින් සමාලෝචනය කර, සංස්කරණය කර, අනුමත කරනු ලබන අතර, අප පළ කරන සියල්ල සඳහා සංස්කාරක කණ්ඩායම වගකිව යුතුය. කරුණු තහවුරු කිරීම සඳහා කෘත්‍රිම බුද්ධි මෙවලම් භාවිත නොකෙරේ."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"පැමිණිලි"}]},{"type":"paragraph","content":[{"type":"text","text":"අප මෙම ප්‍රමිතීන් සපුරා නැතැයි ඔබ විශ්වාස කරන්නේ නම්, අපගේ "},{"type":"text","text":"සම්බන්ධතා පිටුව","marks":[{"type":"link","attrs":{"href":"/si/contact"}}]},{"type":"text","text":" හරහා අප අමතන්න. [[පැමිණිලි හසුරුවන ආකාරය සහ පිළිතුරු දීමට ගතවන කාලය විස්තර කරන්න.]]"}]}]}$page$::jsonb, $page$පුවත් වාර්තා කිරීම, තහවුරු කිරීම, නිවැරදි කිරීම සහ ඉදිරිපත් කිරීමේදී RSnewslk.com අනුගමනය කරන ප්‍රමිතීන්.$page$, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "StaticPageTranslation" ("id", "pageId", "locale", "title", "body", "metaDescription", "updatedAt") VALUES ('static_editorial_en', 'static_editorial', 'en', $page$Editorial policy$page$, $page${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This policy describes the standards we follow in gathering, checking and publishing news. [[Review these standards with your editorial team and adjust them to how you actually work.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Editorial independence"}]},{"type":"paragraph","content":[{"type":"text","text":"Our editorial decisions are made by our editors on the basis of news value and public interest. Advertisers, sponsors, owners, political parties and other outside interests do not decide what we report or how we report it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Accuracy and verification"}]},{"type":"paragraph","content":[{"type":"text","text":"We aim to get the facts right. Before publishing, we check information with reliable sources and, where possible, with more than one source. When information cannot yet be confirmed, we say so clearly, and we do not present rumours or allegations as facts. We take particular care with figures, names, dates and quotations."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sources"}]},{"type":"paragraph","content":[{"type":"text","text":"We prefer named, first-hand sources. We use anonymous sources only when the information is important and cannot be obtained otherwise, and we explain why the source was not named. We protect the identity of confidential sources."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Fairness and impartiality"}]},{"type":"paragraph","content":[{"type":"text","text":"We report fairly and without bias. When we report criticism or allegations against people or organisations, we make a reasonable effort to give them a chance to respond, and we report their response."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Separation of news, opinion and advertising"}]},{"type":"paragraph","content":[{"type":"text","text":"News reports are kept separate from opinion. Advertisements are clearly identified, and paid content is never presented as independent news."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Corrections"}]},{"type":"paragraph","content":[{"type":"text","text":"When we make a significant mistake, we correct it promptly and say that the article has been corrected. Minor errors such as spelling may be fixed without a note. To report an error, see our "},{"type":"text","text":"Contact page","marks":[{"type":"link","attrs":{"href":"/en/contact"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Privacy, harm and sensitive subjects"}]},{"type":"paragraph","content":[{"type":"text","text":"We respect people's privacy and intrude on it only when there is a clear public interest. We take special care when reporting on children, victims of crime, people in grief, suicide and mental health, and we avoid unnecessary graphic detail."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Conflicts of interest"}]},{"type":"paragraph","content":[{"type":"text","text":"Our journalists do not report on matters in which they have a personal, financial or family interest, and they do not accept gifts or payments that could influence their reporting. [[Add your own rules, for example on gifts and outside work.]]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Use of artificial intelligence"}]},{"type":"paragraph","content":[{"type":"text","text":"We may use AI tools to help with tasks such as translating between Sinhala and English, correcting grammar or suggesting headlines. Every such text is reviewed, edited and approved by a member of our editorial team before publication, and the editorial team remains responsible for everything we publish. AI tools are not used to verify facts."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Complaints"}]},{"type":"paragraph","content":[{"type":"text","text":"If you believe we have not met these standards, contact us through our "},{"type":"text","text":"Contact page","marks":[{"type":"link","attrs":{"href":"/en/contact"}}]},{"type":"text","text":". [[Describe how complaints are handled and how long a response takes.]]"}]}]}$page$::jsonb, $page$The standards RSnewslk.com follows in reporting, verifying, correcting and presenting the news.$page$, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
